-- Programme taxonomy only: preserve basic-information, career and curriculum provenance.
ALTER TABLE programmes
    ADD COLUMN taxonomy_source_type VARCHAR(20),
    ADD COLUMN taxonomy_source_url VARCHAR(1000),
    ADD COLUMN taxonomy_source_checked_at TIMESTAMPTZ,
    ADD CONSTRAINT ck_programmes_taxonomy_source_type CHECK (
        taxonomy_source_type IS NULL OR taxonomy_source_type IN ('official', 'third_party', 'ai_generated')
    );

CREATE TEMP TABLE reviewed_programme_taxonomy (
    university_slug VARCHAR(200) NOT NULL,
    programme_code VARCHAR(64) PRIMARY KEY,
    verified BOOLEAN NOT NULL,
    name_zh TEXT,
    name_en TEXT,
    study_level_code VARCHAR(64),
    category_code VARCHAR(64),
    source_url TEXT,
    checked_at TIMESTAMPTZ
) ON COMMIT DROP;

DO $$
BEGIN
    IF (SELECT count(*) FROM reviewed_programme_taxonomy) <> 2233 THEN
        RAISE EXCEPTION 'Expected complete coverage of 2233 audited programme codes';
    END IF;
    IF EXISTS (
        SELECT 1 FROM reviewed_programme_taxonomy reviewed
        JOIN programmes programme ON programme.programme_code = reviewed.programme_code
        JOIN universities university ON university.id = programme.university_id
        LEFT JOIN countries country ON country.id = university.country_id
        WHERE university.slug <> reviewed.university_slug
           OR NOT (country.code = 'MY' OR lower(university.country) = 'malaysia')
    ) THEN
        RAISE EXCEPTION 'Audited programme code has unexpected university or country ownership';
    END IF;
    IF EXISTS (
        SELECT 1 FROM reviewed_programme_taxonomy reviewed
        JOIN programmes programme ON programme.programme_code = reviewed.programme_code
        LEFT JOIN study_levels level ON level.code = reviewed.study_level_code
        LEFT JOIN subject_categories category ON category.code = reviewed.category_code
        WHERE reviewed.verified AND (level.id IS NULL OR category.id IS NULL)
    ) THEN
        RAISE EXCEPTION 'Verified taxonomy references missing dictionaries';
    END IF;
END $$;

UPDATE programmes programme
SET name_zh = reviewed.name_zh,
    name_en = reviewed.name_en,
    study_level_id = level.id,
    subject_category_id = category.id,
    taxonomy_source_type = 'official',
    taxonomy_source_url = reviewed.source_url,
    taxonomy_source_checked_at = reviewed.checked_at,
    status = 'PUBLISHED',
    published_at = COALESCE(programme.published_at, CURRENT_TIMESTAMP),
    updated_at = CURRENT_TIMESTAMP
FROM reviewed_programme_taxonomy reviewed
JOIN universities university ON university.slug = reviewed.university_slug
JOIN study_levels level ON level.code = reviewed.study_level_code
JOIN subject_categories category ON category.code = reviewed.category_code
WHERE reviewed.verified
  AND programme.programme_code = reviewed.programme_code
  AND programme.university_id = university.id
  AND programme.status IN ('PUBLISHED', 'DRAFT');

UPDATE programmes programme
SET status = CASE WHEN programme.status = 'PUBLISHED' THEN 'DRAFT' ELSE programme.status END,
    published_at = CASE WHEN programme.status = 'PUBLISHED' THEN NULL ELSE programme.published_at END,
    taxonomy_source_type = COALESCE(programme.taxonomy_source_type, 'third_party'),
    taxonomy_source_url = COALESCE(programme.taxonomy_source_url,
        'https://github.com/xw042543-commits/company-website/blob/main/outputs/university-data-cleaned-20260928/postgres-import/programmes.csv'),
    taxonomy_source_checked_at = COALESCE(programme.taxonomy_source_checked_at, CURRENT_TIMESTAMP),
    updated_at = CURRENT_TIMESTAMP
FROM reviewed_programme_taxonomy reviewed
JOIN universities university ON university.slug = reviewed.university_slug
WHERE NOT reviewed.verified
  AND programme.programme_code = reviewed.programme_code
  AND programme.university_id = university.id;

SELECT DISTINCT university.id, 'PENDING', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
FROM universities university
JOIN reviewed_programme_taxonomy reviewed ON reviewed.university_slug = university.slug
WHERE NOT EXISTS (
    SELECT 1 FROM search_sync_jobs job
    WHERE job.university_id = university.id AND job.status IN ('PENDING', 'PROCESSING')
);

DO $$
BEGIN
    IF EXISTS (
        SELECT 1 FROM reviewed_programme_taxonomy reviewed
        JOIN programmes programme ON programme.programme_code = reviewed.programme_code
        JOIN universities university ON university.id = programme.university_id
        JOIN study_levels level ON level.id = programme.study_level_id
        JOIN subject_categories category ON category.id = programme.subject_category_id
        WHERE university.slug = reviewed.university_slug
          AND programme.status <> 'ARCHIVED'
          AND reviewed.verified
          AND (programme.name_zh IS DISTINCT FROM reviewed.name_zh
            OR programme.name_en IS DISTINCT FROM reviewed.name_en
            OR level.code IS DISTINCT FROM reviewed.study_level_code
            OR category.code IS DISTINCT FROM reviewed.category_code
            OR programme.taxonomy_source_type IS DISTINCT FROM 'official'
            OR programme.taxonomy_source_url IS DISTINCT FROM reviewed.source_url
            OR programme.taxonomy_source_checked_at IS DISTINCT FROM reviewed.checked_at
            OR programme.status IS DISTINCT FROM 'PUBLISHED')
    ) THEN
        RAISE EXCEPTION 'Verified programme taxonomy failed write-back validation';
    END IF;
    IF EXISTS (
        SELECT 1 FROM reviewed_programme_taxonomy reviewed
        JOIN programmes programme ON programme.programme_code = reviewed.programme_code
        WHERE NOT reviewed.verified AND programme.status = 'PUBLISHED'
    ) THEN
        RAISE EXCEPTION 'An unconfirmed audited programme remains publicly published';
    END IF;
END $$;
